<script setup lang="ts">import {computed,ref} from "vue";import {useRoute} from "vue-router";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import Tabs from "@/components/zs/Tabs.vue";import StatusBadge from "@/components/zs/StatusBadge.vue";import ZButton from "@/components/zs/ZButton.vue";import ActivityTimeline from "@/components/crm/ActivityTimeline.vue";import {useAsyncData} from "@/composables/useAsyncData";import {crmRepository} from "@/services/crm/repository";import {useCompanyStore} from "@/stores/company";import {formatMoney} from "@/lib/money";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";setPageMeta('Deal Detail','Commercial terms, stage, contacts, activity and execution steps.');const route=useRoute(),c=useCompanyStore(),deals=useAsyncData(()=>crmRepository.deals(c.activeCompanyId),{watch:[()=>c.activeCompanyId]}),acts=useAsyncData(()=>crmRepository.activities(c.activeCompanyId),{watch:[()=>c.activeCompanyId]}),tab=ref('Overview'),item=computed(()=>deals.data.value?.find(x=>x.id===route.params.id)),activity=computed(()=>acts.data.value?.filter(x=>x.accountId===item.value?.accountId)??[]);</script><template><AppShell><template v-if="item"><PageHeader :title="item.name" :description="`${item.company} · ${formatMoney(item.value)}`"><template #actions><StatusBadge :status="item.stage"/><ZButton variant="outline">Edit deal</ZButton><ZButton @click="showToast('Activity prepared','The CRM API will persist the final activity.','info')">Log activity</ZButton></template></PageHeader><div class="grid gap-4 xl:grid-cols-[1fr_20rem]"><Panel><Tabs v-model="tab" :items="['Overview','Activity','Notes','Attachments']"/><div v-if="tab==='Overview'" class="grid gap-5 p-5 sm:grid-cols-2"><div v-for="[k,v] in Object.entries({Company:item.company,Contact:item.contact,Stage:item.stage,Value:formatMoney(item.value),Probability:`${item.probability}%`,'Expected close':item.expectedClose,Owner:item.owner,Source:item.source})" :key="k"><p class="label-caps">{{k}}</p><p class="mt-1 text-sm text-content">{{v}}</p></div></div><div v-else-if="tab==='Activity'" class="p-4"><ActivityTimeline :items="activity"/></div><div v-else class="p-10 text-center text-sm text-content-muted">No {{tab.toLowerCase()}} recorded yet.</div></Panel><div class="space-y-4"><Panel title="Next step"><div class="p-4"><p class="text-sm font-medium text-content">{{item.nextStep}}</p><p class="mt-1 text-xs text-content-muted">Due before {{item.expectedClose}}</p></div></Panel><Panel title="Stage probability"><div class="p-4"><div class="h-2 rounded-full bg-surface-sunken"><div class="h-full rounded-full bg-primary" :style="{width:`${item.probability}%`}"></div></div><p class="num mt-2 text-right text-xs text-content-secondary">{{item.probability}}%</p></div></Panel></div></div></template><Panel v-else><p class="p-8 text-center text-sm text-content-muted">Deal unavailable in the active company.</p></Panel></AppShell></template>